{
  "justification": "Using the unprompted, multi-response Ipsos Issues Index, I mapped each named issue to the Moral Foundations it most plausibly invokes and weighted foundations by the reported salience shares, then normalized to sum to 1. Because the instrument records mentions without direction, the profile reflects relative emphasis on moral themes in concerns rather than support for any particular stance.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Education/Schools; Unemployment/Factory closure/Lack of industry (harm to livelihoods); Crime/Law and order (victims); Pensions/Social security; Housing; Inflation/Prices; Drug abuse; Pollution/Environment; BSE/Beef",
      "weight": 0.38041
    },
    {
      "foundation": "equality",
      "basis": "NHS/Hospitals/Healthcare (access); Education/Schools (opportunity); Pensions/Social security; Housing; Taxation (redistribution/fair treatment); Race relations/Immigration/Immigrants",
      "weight": 0.20052
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Common Market/EU/Europe/Single European Currency (rules/governance); Economy/Economic situation (stewardship); Morality/Individual behaviour; Drug abuse; Northern Ireland; Defence/Foreign affairs/International terrorism; Local government/Council tax/Poll tax; BSE/Beef; Privitisation",
      "weight": 0.15086
    },
    {
      "foundation": "proportionality",
      "basis": "Education/Schools (merit/reward); Unemployment/Factory closure/Lack of industry; Economy/Economic situation; Taxation; Inflation/Prices; Local government/Council tax/Poll tax; Privitisation",
      "weight": 0.12474
    },
    {
      "foundation": "loyalty",
      "basis": "Common Market/EU/Europe/Single European Currency (sovereignty/tribe); Northern Ireland; Race relations/Immigration/Immigrants (in‑group/out‑group); Defence/Foreign affairs/International terrorism",
      "weight": 0.10412
    },
    {
      "foundation": "sanctity",
      "basis": "Morality/Individual behaviour; Drug abuse; Pollution/Environment; BSE/Beef; Crime/Law and order/Violence/Vandalism (decency/contamination)",
      "weight": 0.03935
    }
  ]
}
